from topics_a import t, T
# bookkeepers
t('bookkeeper','bookkeeper','a bookkeeper',"A bookkeeper records sales, purchases, receipts and payments, reconciles bank accounts and often prepares VAT returns and payroll, so your numbers are accurate all year.",["Monthly bookkeeping makes year end faster and cheaper.","Clean books help you spot cash-flow problems early.","Agree how you will share documents each month."])
t('bookkeeping','bookkeeper','bookkeeping services',"Bookkeeping services keep your financial records up to date, from bank reconciliations and invoices to VAT returns and management reports.",["Choose a frequency that matches your transaction volume.","Cloud software lets you see the same numbers as your bookkeeper.","Ask about catch-up work if you are behind."])
t('small-business-bookkeeper','bookkeeper','a small business bookkeeper',"Small business bookkeepers help owner-managers stay on top of invoices, receipts and VAT without hiring in-house staff.",["Outsourcing lets you focus on running the business.","A short monthly report keeps you informed.","Ask about chasing unpaid invoices."])
t('startup-bookkeeper','bookkeeper','a bookkeeper for start-ups',"Start-ups benefit from setting up software, categories and processes correctly from the beginning, making investment and growth easier later.",["Good set-up saves expensive clean-ups.","Investors expect tidy records.","Ask about cash runway reporting."])
t('freelance-bookkeeper','bookkeeper','a freelance bookkeeper',"Freelance bookkeepers often work for several small clients, offering flexibility and personal service.",["Check AML supervision and insurance.","Agree holiday cover arrangements.","Confirm data security practices."])
t('virtual-bookkeeper','bookkeeper','a virtual bookkeeper',"Virtual bookkeepers work remotely through cloud software, bank feeds and document apps, so location matters less.",["Ask which receipt-capture tools they use.","Agree response times.","Check how access is granted and removed."])
t('contractor-bookkeeper','bookkeeper','a bookkeeper for contractors',"Contractors operating through limited companies need invoices, expenses and VAT kept tidy, with records that support IR35 positions.",["Keep contracts and timesheets with your records.","Flat rate VAT may or may not suit you.","Track expenses carefully."])
t('ecommerce-bookkeeper','bookkeeper','an e-commerce bookkeeper',"E-commerce bookkeepers reconcile marketplace payouts, payment processors, refunds and stock across platforms.",["Integration apps can automate much of the work.","Ask about multi-currency handling.","Stock reconciliation affects profit."])
t('restaurant-bookkeeper','bookkeeper','a restaurant bookkeeper',"Restaurant bookkeepers handle daily takings, tips, supplier invoices and payroll for shift-based teams.",["Daily till reconciliations prevent errors.","Supplier price changes affect margins.","Tronc and tips need careful recording."])
t('retail-bookkeeper','bookkeeper','a retail bookkeeper',"Retail bookkeepers reconcile tills and card payments, track stock and prepare VAT returns for shops.",["EPOS integration reduces manual work.","Stock counts support accurate accounts.","Seasonal cash flow needs planning."])
t('charity-bookkeeper','bookkeeper','a charity bookkeeper',"Charity bookkeepers track restricted and unrestricted funds, donations and Gift Aid, ready for independent examination.",["Fund accounting is essential.","Keep Gift Aid declarations organised.","Trustees need clear reports."])
t('landlord-bookkeeper','bookkeeper','a bookkeeper for landlords',"Landlord bookkeepers record rent, letting agent statements, repairs and mortgage costs property by property.",["Separate records per property help at tax time.","Agent statements need reconciling.","Keep capital improvements separate."])
t('xero-bookkeeper','bookkeeper','a Xero bookkeeper',"Xero bookkeepers are trained in Xero's bank feeds, rules, invoicing and reporting, and many are Xero certified advisors.",["Ask for Xero certification.","Bank rules speed up reconciliation.","Add-on apps can automate receipts."])
t('quickbooks-bookkeeper','bookkeeper','a QuickBooks bookkeeper',"QuickBooks bookkeepers set up and maintain QuickBooks Online, including bank rules, invoicing and VAT submissions.",["QuickBooks ProAdvisor status shows training.","Clean categories make reports useful.","Ask about migrating from desktop versions."])
t('sage-bookkeeper','bookkeeper','a Sage bookkeeper',"Sage bookkeepers work in Sage Accounting or Sage 50, handling ledgers, VAT and payroll for businesses that already use Sage.",["Sage experience matters for older desktop set-ups.","Ask about payroll modules.","Backups and access control are important."])

# tax
t('tax-advisor','tax','a tax adviser',"A tax adviser helps you understand and manage your tax position, from personal returns and property sales to business structures and HMRC disputes.",["Advice before a transaction is more valuable than after.","Ask for advice in writing.","Check qualifications such as CTA or ATT."])
t('tax-consultant','tax','a tax consultant',"Tax consultants give specialist advice on complex areas such as reliefs, restructures, international tax and disputes.",["Specialist advice is best for one-off, high-value decisions.","Ask for a fixed fee for defined work.","Make sure your accountant is kept informed."])
t('independent-tax-advisor','tax','an independent tax adviser',"Independent tax advisers work outside large firms, often offering partner-level attention and specialist focus.",["Check qualifications and insurance.","Independent advisers may cost less for focused work.","Ask about their network for wider issues."])
t('hmrc-tax-advisor','tax','an adviser for HMRC matters',"Advisers who deal with HMRC help with letters, compliance checks, penalties, disclosures and negotiating time to pay.",["Respond to HMRC deadlines.","Voluntary disclosure usually leads to lower penalties.","Ask about time-to-pay arrangements."])
t('tax-investigation-advisor','tax','a tax investigation specialist',"Tax investigation specialists represent you in HMRC enquiries, compliance checks and Code of Practice 8 or 9 investigations.",["Do not ignore letters about COP9.","Fee protection insurance may cover costs.","Specialists manage communication with HMRC."])
t('tax-appeal-advisor','tax','a tax appeal adviser',"Tax appeal advisers help you challenge HMRC decisions through statutory review or the First-tier Tribunal.",["Appeals usually have a 30-day deadline.","A review can resolve some disputes without a tribunal.","Evidence and arguments must be organised."])
t('vat-advisor','tax','a VAT adviser',"VAT advisers help with registration, schemes, partial exemption, property VAT, imports and exports, and HMRC VAT disputes.",["The wrong VAT treatment can be costly.","Property transactions need VAT checks before contracts.","Ask about the flat rate scheme's suitability."])
t('corporation-tax-advisor','tax','a corporation tax adviser',"Corporation tax advisers help companies plan profits, claim reliefs such as R&D and capital allowances, and structure groups.",["Plan before year end.","R&D claims face HMRC scrutiny; get them right.","Group relief can shelter profits."])
t('payroll-tax-advisor','tax','a payroll tax adviser',"Payroll tax advisers handle PAYE, National Insurance, benefits in kind, employment status and termination payments.",["P11D benefits must be reported.","Employment status mistakes carry risk.","Salary sacrifice needs careful design."])
t('cis-tax-advisor','tax','a CIS tax adviser',"CIS tax advisers help with gross payment status, deductions, refunds and HMRC compliance under the Construction Industry Scheme.",["Gross payment status needs a clean compliance record.","Verify subcontractors before paying.","Late returns attract penalties."])
t('crypto-tax-advisor','tax','a crypto tax adviser',"Crypto tax advisers apply HMRC rules to trading, staking, DeFi and NFTs, and help with disclosures of past gains.",["Keep complete transaction histories.","HMRC receives data from exchanges.","Disclosing past gains voluntarily reduces penalties."])
t('landlord-tax-advisor','tax','a landlord tax adviser',"Landlord tax advisers look at income tax, capital gains, inheritance tax and ownership structures across property portfolios.",["Incorporation is not right for everyone.","Gains on residential property must be reported quickly.","Joint ownership can be structured."])
t('expat-tax-advisor','tax','an expat tax adviser',"Expat tax advisers deal with residence, domicile and the new foreign income regime, double tax treaties and UK income while abroad.",["Residence is decided by the Statutory Residence Test.","Plan before leaving or returning.","Treaties can prevent double taxation."])
t('offshore-tax-advisor','tax','an offshore tax adviser',"Offshore tax advisers help with overseas income, trusts and accounts, and with disclosing previously unreported offshore matters.",["HMRC receives information through international agreements.","Disclosure facilities can reduce penalties.","Trusts abroad have complex UK rules."])
t('inheritance-tax-advisor','tax','an inheritance tax adviser',"Inheritance tax advisers plan lifetime gifts, trusts, reliefs such as business and agricultural relief, and wills to reduce tax lawfully.",["Gifts can fall out of the estate after seven years.","Relief rules are changing; get up-to-date advice.","Planning should fit your family's needs."])
t('inheritance-tax-return','tax','an inheritance tax return',"Executors may need to file an IHT400 inheritance tax account, value the estate and pay any tax before probate can be granted.",["Valuations need to be accurate.","Interest runs on tax paid late.","Some estates qualify as excepted estates."])
t('ir35-advisor','tax','an IR35 adviser',"IR35 advisers review contracts and working practices to assess employment status, and help contractors and clients respond to status determinations.",["Working practices matter as much as the contract.","Medium and large clients make the status decision.","Disputes can be raised with the client."])
t('ir35-consultant','tax','an IR35 consultant',"IR35 consultants provide contract reviews, status assessments and support during HMRC enquiries for contractors and hiring businesses.",["Ask for a written assessment.","Review again when roles change.","Check insurance options."])
t('ir35-help','tax','help with IR35',"If you are unsure how IR35 affects your contract, an expert can explain the rules, review your arrangements and help you plan.",["Do not rely on online tools alone.","Keep evidence of substitution and control.","Get advice before signing."])
t('ir35-specialist','tax','an IR35 specialist',"IR35 specialists focus on employment status law and HMRC practice, representing contractors and businesses in disputes.",["Specialists understand tribunal decisions.","Representation helps in HMRC enquiries.","Ask about success in similar cases."])
t('eis-advisor','tax','an EIS adviser',"EIS advisers help companies get advance assurance and comply with Enterprise Investment Scheme rules, and help investors understand reliefs and risks.",["Advance assurance gives investors confidence.","Rules on qualifying trades are strict.","Investors face higher risks in early-stage companies."])
t('eis-consultant','tax','an EIS consultant',"EIS consultants prepare advance assurance applications, compliance statements and investor certificates for growing companies.",["Prepare a clear business plan.","Use of funds must meet the rules.","Compliance continues after investment."])
t('eis-help','tax','help with EIS',"If you are raising money or investing under the Enterprise Investment Scheme, expert help makes sure reliefs are claimed correctly.",["Mistakes can cost investors their relief.","Keep records of share issues.","Ask about SEIS too."])
t('eis-specialist','tax','an EIS specialist',"EIS specialists understand the detailed conditions for companies and investors, including risk-to-capital rules.",["The risk-to-capital condition matters.","Funding limits apply.","Ask for experience with your sector."])
t('eis-tax-advisor','tax','an EIS tax adviser',"EIS tax advisers explain income tax relief, capital gains deferral and loss relief for investors, and compliance for companies.",["Reliefs depend on holding periods.","Losses can be set against income.","Keep EIS3 certificates safe."])
t('seis-advisor','tax','an SEIS adviser',"SEIS advisers help very early-stage companies apply for advance assurance and issue shares that qualify for Seed Enterprise Investment Scheme relief.",["SEIS has lower limits than EIS.","Timing of share issues matters.","Combine with EIS carefully."])
t('csop-advisor','tax','a CSOP adviser',"CSOP advisers design and implement Company Share Option Plans, a tax-advantaged way to offer share options to staff.",["Valuations are agreed with HMRC.","Compare with EMI options.","Plan rules must be followed."])
t('cetv-advice','pension','advice on a CETV',"A cash equivalent transfer value (CETV) is the amount a defined benefit pension scheme offers if you transfer out, and transfers above a set value require advice from a pension transfer specialist.",["Most people are better off keeping guaranteed benefits.","Transfer quotes are only guaranteed for a limited time.","Advice must compare benefits carefully."])
t('trusts-advisor','tax','a trusts adviser',"Trusts advisers help set up and run trusts, handle trust tax returns, the ten-year charge and registration with the Trust Registration Service.",["Most trusts must be registered.","Trusts have their own tax rules.","Trustees have legal duties."])
t('trust-registration','tax','trust registration',"Most UK express trusts, and some non-UK trusts, must be registered on HMRC's Trust Registration Service, and the register must be kept up to date.",["Deadlines apply after a trust is created.","Changes must be updated.","Penalties can apply for late registration."])
